const applyStaffSession=(s)=>{if(!s)return;const permissions=s.permissions||[];document.querySelectorAll('nav button[data-permission]').forEach(btn=>{const required=btn.dataset.permission;const aliases={inventory_read:'inventory',finance_read:'finance'};const permitted=permissions.includes(required)||(aliases[required]&&permissions.includes(aliases[required]));if(!permitted||(operatorMode&&!['floor','orders'].includes(required)))btn.hidden=true;});const user=document.querySelector('.user');if(user)user.innerHTML='● &nbsp; '+(operatorMode?'Рабочее место':s.user.name)+'<br><small>'+(operatorMode?'режим сотрудника':(staffRoleLabels[s.user.role]||s.user.role))+'</small><button class="staff-logout" id="logout" type="button">Выйти</button>';};
