const staticStaffDemo=()=>String(localStorage.getItem('crm_session_token')||'').startsWith('demo-static-');
const localOrders=()=>{try{return JSON.parse(localStorage.getItem('territory_crm_staff_orders')||'[]');}catch(_){return[];}};
const saveLocalOrders=(items)=>localStorage.setItem('territory_crm_staff_orders',JSON.stringify(items));
const localApprovedDiscountTotal=(orderId,subtotal)=>{let requests=[];try{requests=JSON.parse(localStorage.getItem('territory_crm_discount_requests')||'[]');}catch(_){requests=[];}return requests.filter((request)=>request.orderId===orderId&&request.status==='approved').reduce((sum,request)=>sum+(request.type==='percent'?subtotal*Math.min(100,Math.max(0,Number(request.value||0)))/100:Math.max(0,Number(request.value||0))),0);};
const staticAuditEvent=(action,entityId,details={})=>{if(!staticStaffDemo())return;let events=[];try{events=JSON.parse(localStorage.getItem('territory_crm_demo_audits')||'[]');}catch(_){events=[];}const user=JSON.parse(localStorage.getItem('crm_session_user')||'{}');events.push({id:`local-audit-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,action,entity:'order',entityType:'order',entityId,actor:user.name||'сотрудник',createdAt:new Date().toISOString(),details});localStorage.setItem('territory_crm_demo_audits',JSON.stringify(events.slice(-300)));};
const localOrderStatusTransitions={open:['open','in_progress','cancelled'],in_progress:['in_progress','ready','open','cancelled'],ready:['ready','closed','in_progress','cancelled'],closed:['closed'],cancelled:['cancelled']};
const staticOrderApi=async(url,options={})=>{const path=new URL(url,location.origin).pathname;const method=options.method||'GET';const input=options.body?JSON.parse(options.body):{};let list=localOrders();const orderEdit=path.match(/^\/api\/orders\/([^/]+)$/);if(orderEdit&&method==='PATCH'){const order=list.find(x=>x.id===orderEdit[1]);if(!order)throw new Error('HTTP 404');if(input.notes!==undefined)order.notes=String(input.notes||'').slice(0,2000);if(input.guestName!==undefined||input.phone!==undefined){const phone=String(input.phone||'').trim();if(phone&&!/^\+?[0-9 ()-]{7,24}$/.test(phone))throw new Error('invalid_guest_phone');order.guestName=String(input.guestName||'').trim().slice(0,120);order.guestPhone=phone;}saveLocalOrders(list);return {...order,guestName:order.guestName,phone:order.guestPhone};}if(path==='/api/orders'&&method==='GET')return{items:list};if(path==='/api/orders'&&method==='POST'){const minimumOrderTotal=Number(input.minimumOrderTotal||0);const tableId=String(input.tableId||'').trim();if(!tableId||tableId.length>80)throw new Error('table_id_required');if(!Number.isFinite(minimumOrderTotal)||minimumOrderTotal<0)throw new Error('invalid_vip_minimum');const order={id:`local-order-${Date.now()}`,tableId,minimumOrderTotal,status:'open',items:[]};list.push(order);staticAuditEvent('order.created',order.id,{tableId:order.tableId,minimumOrderTotal:order.minimumOrderTotal});saveLocalOrders(list);return order;}const item=path.match(/^\/api\/orders\/([^/]+)\/items(?:\/([^/]+))?$/);if(item&&method==='POST'){const order=list.find(x=>x.id===item[1]);if(!order||['closed','cancelled'].includes(order.status))throw new Error('order_not_editable');const quantity=Number(input.quantity||1);if(!Number.isInteger(quantity)||quantity<1||quantity>999)throw new Error('invalid_quantity');const product=products.find(x=>x[4]===input.productId||x[0]===input.productId);const added={id:`local-item-${Date.now()}`,productId:input.productId,name:product?.[0]||input.productId,quantity,unitPrice:Number(product?.[1]||0)};order.items.push(added);saveLocalOrders(list);return added;}if(item&&(method==='PATCH'||method==='DELETE')){const order=list.find(x=>x.id===item[1]);const entry=order?.items?.find(x=>x.id===item[2]);if(!entry)throw new Error('HTTP 404');if(method==='DELETE'){order.items=order.items.filter(x=>x.id!==entry.id);staticAuditEvent('order.item_removed',order.id,{itemId:entry.id});saveLocalOrders(list);return{id:entry.id};}const quantity=Number(input.quantity);if(!Number.isInteger(quantity)||quantity<1||quantity>999)throw new Error('invalid_quantity');const before=entry.quantity;entry.quantity=quantity;staticAuditEvent('order.item_quantity_changed',order.id,{itemId:entry.id,from:before,to:quantity});saveLocalOrders(list);return entry;}const action=path.match(/^\/api\/orders\/([^/]+)\/(status|transfer|close|payments|discount-requests)$/);if(action){const order=list.find(x=>x.id===action[1]);if(!order)throw new Error('HTTP 404');if(action[2]==='discount-requests'){const type=String(input.type||'percent');const value=Number(input.value);const reason=String(input.reason||'').trim();if(!['percent','fixed'].includes(type)||!Number.isFinite(value)||value<=0||(type==='percent'&&value>100)||!reason||reason.length>500)throw new Error('invalid_discount_request');const key='territory_crm_discount_requests';let requests=[];try{requests=JSON.parse(localStorage.getItem(key)||'[]');}catch(_){requests=[];}const request={id:`local-discount-${Date.now()}`,orderId:order.id,type,value,reason,guestName:order.guestName||null,guestPhone:order.guestPhone||null,status:'requested',requestedBy:JSON.parse(localStorage.getItem('crm_session_user')||'{}').name||'сотрудник',createdAt:new Date().toISOString()};requests.push(request);localStorage.setItem(key,JSON.stringify(requests));staticAuditEvent('discount.requested',order.id,{requestId:request.id,type:request.type,value:request.value,reason:request.reason});return request;}if(action[2]==='status'){if(!localOrderStatusTransitions[order.status]?.includes(input.status))throw new Error('invalid_order_transition');const before=order.status;order.status=input.status;staticAuditEvent('order.status_changed',order.id,{from:before,to:input.status});}if(action[2]==='transfer'){const tableId=String(input.tableId||'').trim();if(!tableId||tableId.length>80)throw new Error('table_id_required');const before=order.tableId;order.tableId=tableId;staticAuditEvent('order.transferred',order.id,{from:before,to:input.tableId});}if(action[2]==='close'){if(!['open','in_progress','ready'].includes(order.status))throw new Error('invalid_order_transition');if(!['cash','card','qr'].includes(String(input.paymentMethod||'cash')))throw new Error('valid_payment_method_required');order.status='closed';order.closedAt=new Date().toISOString();const subtotal=(order.items||[]).reduce((s,x)=>s+x.unitPrice*x.quantity,0);order.subtotal=subtotal;const discount=localApprovedDiscountTotal(order.id,subtotal);order.discountTotal=discount;order.finalTotal=Math.max(subtotal-discount,Number(order.minimumOrderTotal||0));order.payments ||= [];const alreadyPaid=order.payments.filter((payment)=>payment.status==='paid').reduce((sum,payment)=>sum+Number(payment.amount||0),0);const remaining=Math.max(0,order.finalTotal-alreadyPaid);if(remaining>0)order.payments.push({id:`local-pay-${Date.now()}`,method:input.paymentMethod||'cash',amount:remaining,status:'paid',createdAt:new Date().toISOString()});order.paid=alreadyPaid+remaining;order.remaining=0;order.minimumAdjustment=Math.max(0,Number(order.minimumOrderTotal||0)-(subtotal-discount));order.paymentMethod=input.paymentMethod||'cash';staticAuditEvent('order.closed',order.id,{finalTotal:order.finalTotal,discountTotal:discount,minimumAdjustment:order.minimumAdjustment,paymentMethod:order.paymentMethod});}if(action[2]==='payments'){if(['closed','cancelled'].includes(order.status)&&method==='POST')throw new Error('order_already_final');order.payments ||= [];const subtotal=(order.items||[]).reduce((s,x)=>s+x.unitPrice*x.quantity,0);const due=Math.max(subtotal-localApprovedDiscountTotal(order.id,subtotal),Number(order.minimumOrderTotal||0));const paid=order.payments.reduce((sum,x)=>sum+Number(x.amount),0);if(method==='GET')return{items:order.payments,due,paid,remaining:Math.max(0,due-paid)};const amount=Number(input.amount);if(!['cash','card','qr'].includes(String(input.method||'cash'))||!Number.isFinite(amount)||amount<=0||paid+amount>due+0.01)throw new Error('HTTP 409');const payment={id:`local-pay-${Date.now()}`,method:input.method||'cash',amount,status:'paid',createdAt:new Date().toISOString()};order.payments.push(payment);const nextPaid=paid+amount;if(nextPaid>=due)order.status='closed';staticAuditEvent('order.payment_added',order.id,{paymentId:payment.id,method:payment.method,amount:payment.amount,paid:nextPaid,remaining:Math.max(0,due-nextPaid)});saveLocalOrders(list);return{...payment,due,paid:nextPaid,remaining:Math.max(0,due-nextPaid),closed:nextPaid>=due};}saveLocalOrders(list);return order;}return{};};
const staticSplitApi=async(url,options={})=>{const path=new URL(url,location.origin).pathname;const match=path.match(/^\/api\/orders\/([^/]+)\/split$/);if(!match)return null;const input=options.body?JSON.parse(options.body):{};const list=localOrders();const source=list.find((x)=>x.id===match[1]);if(!source)throw new Error('HTTP 404');if(!['open','in_progress','ready'].includes(source.status))throw new Error('invalid_order_transition');const ids=new Set(Array.isArray(input.itemIds)?input.itemIds:[]);if(!ids.size)throw new Error('HTTP 400');const moved=(source.items||[]).filter((x)=>ids.has(x.id));if(!moved.length)throw new Error('HTTP 400');source.items=(source.items||[]).filter((x)=>!ids.has(x.id));const target={id:`local-order-${Date.now()}`,tableId:source.tableId,status:'open',minimumOrderTotal:0,guestName:source.guestName||null,guestPhone:source.guestPhone||null,items:moved,splitFrom:source.id};list.push(target);staticAuditEvent('order.split',source.id,{targetOrderId:target.id,itemIds:[...ids],movedCount:moved.length});saveLocalOrders(list);return target;};
const apiJson=(url,options={})=>staticStaffDemo()?(url.endsWith('/split')?staticSplitApi(url,options):staticOrderApi(url,options)):fetch(url,{...options,headers:{...sessionHeaders(),...(options.headers||{})}}).then(r=>r.ok?r.json():Promise.reject(new Error(`HTTP ${r.status}`)));
let currentShift=null;
const shiftApi=(options={})=>{if(staticStaffDemo()){let saved;try{saved=JSON.parse(localStorage.getItem('territory_crm_shift')||'null');}catch(_){saved=null;}if(!options.method)return Promise.resolve({items:saved?[saved]:[],current:saved});if(options.method==='POST'&&options.url?.endsWith('/close')){if(!saved) return Promise.reject(new Error('shift_not_open'));if(saved){saved.closedAt=new Date().toISOString();saved.closingCash=Number(JSON.parse(options.body||'{}').closingCash||0);localStorage.setItem('territory_crm_shift',JSON.stringify(saved));}return Promise.resolve(saved);}const input=options.body?JSON.parse(options.body):{};if(saved&&!saved.closedAt)return Promise.reject(new Error('shift_already_open'));saved={id:`local-shift-${Date.now()}`,openedAt:new Date().toISOString(),closedAt:null,openingCash:Number(input.openingCash||0)};localStorage.setItem('territory_crm_shift',JSON.stringify(saved));return Promise.resolve(saved);}return fetch(options.url||'/api/shifts',{...options,headers:{...sessionHeaders(),...(options.headers||{})}}).then(r=>r.ok?r.json():Promise.reject(new Error(`HTTP ${r.status}`)));};
const refreshShift=()=>shiftApi().then((result)=>{currentShift=result.current||null;const button=document.querySelector('#shift-toggle');if(button)button.textContent=currentShift?'● Смена открыта':'○ Открыть смену';}).catch(()=>{});
refreshShift();
const orderRows=document.querySelector('.items');
function drawOrder(order){
  currentOrder=order||null;
  const title=document.querySelector('.order h2');
  const tableLabel=order?.tableId ? ({'vip-room-1':'VIP-комната 1','vip-room-2':'VIP-комната 2'}[String(order.tableId)]||`Стол ${String(order.tableId).replace(/^table-/,'')}`) : 'Стол 8';
  if(title) title.textContent=tableLabel;
  if(!orderRows)return;
  const items=order?.items||[];
  orderRows.innerHTML=items.length?items.map(item=>`<div class="order-item-row" data-item-id="${item.id}"><span>${item.name||item.productName||'Позиция'}</span><span class="quantity-control"><button class="qty-minus" data-item="${item.id}" aria-label="Уменьшить">−</button><b>${item.quantity||1}</b><button class="qty-plus" data-item="${item.id}" aria-label="Увеличить">＋</button></span><b>${Number(item.unitPrice||item.price||0)*(item.quantity||1)} ₽</b></div>`).join(''):'<div class="empty-order">Позиции пока не добавлены</div>';
  const meta=document.querySelector('.meta'); if(meta) meta.textContent=`👥 ${order?.guests||2} гостя${order?.guestName?` · ${order.guestName}`:''}  ·  ⏱ обслуживание`;
  recalc();
}
let queueFilter='all';
function drawQueue(filter=queueFilter){queueFilter=filter;const chips=document.querySelectorAll('.chips span');if(chips.length<4)return;const all=openOrders.filter((order)=>order.status!=='closed'&&order.status!=='cancelled').length;const fresh=openOrders.filter((order)=>order.status==='open').length;const cooking=openOrders.filter((order)=>order.status==='in_progress').length;const ready=openOrders.filter((order)=>order.status==='ready').length;[all,fresh,cooking,ready].forEach((value,index)=>{const labels=['Все','Новый заказ','Готовится','Готово'];chips[index].textContent=`${labels[index]} ${value}`;chips[index].classList.toggle('active',chips[index].dataset.filter===queueFilter);});const list=document.querySelector('#queue-list');if(!list)return;const visible=openOrders.filter((order)=>{if(order.status==='closed'||order.status==='cancelled')return false;return queueFilter==='all'||order.status===queueFilter;});list.innerHTML=visible.length?visible.map((order)=>{const label=order.status==='ready'?'Готово':order.status==='in_progress'?'Готовится':'Новый заказ';const table=String(order.tableId||'').replace(/^table-/,'');const total=(order.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||item.price||0)*Number(item.quantity||1),0);return `<button class="queue-card" data-queue-table="${order.tableId||''}"><span><b>Стол ${table||'—'}</b><small>${(order.items||[]).length} поз. · ${total.toLocaleString('ru-RU')} ₽</small></span><em>${label}</em></button>`;}).join(''):'<div class="queue-empty">В этом разделе пока нет заказов</div>';}

function loadOrders(){return apiJson('/api/orders').then(payload=>{openOrders=payload.items||[]; drawQueue(); const selected=openOrders.find(o=>String(o.tableId)==='table-8'||String(o.tableId)==='8'); drawOrder(selected||{tableId:'table-8',items:[]});}).catch(()=>{openOrders=[];drawQueue();drawOrder({tableId:'table-8',items:[]});});}
loadOrders();
const renderZone=(zone)=>{const serverTables=zone?.tables||[]; if(!serverTables.length)return; serverTables.forEach((t)=>{tableMinimums[t.id]=Number(t.minimumOrderTotal||0);}); tables.innerHTML=serverTables.map(t=>{const label=t.status==='occupied'?'Занят':t.status==='reserved'?'Бронь':'Свободен'; return `<button class="table ${t.status==='occupied'?'busy':t.status==='reserved'?'reserve':'free'} ${t.name==='Стол 8'?'sel':''}" data-table="${t.id}"><strong>${t.name.replace(/^Стол /,'')}</strong><em>${label}</em><small>${t.capacity||'2–4'} гостя</small></button>`}).join('');};
fetch('/api/floor',{headers:sessionHeaders()}).then(r=>r.ok?r.json():null).then(payload=>{serverZones=payload?.zones||[]; renderZone(serverZones[0]);}).catch(()=>{});
if(operatorMode) notice('Открыт временный режим рабочего места. Действия записываются за вашей учётной записью.');
tables.addEventListener('click',event=>{const card=event.target.closest('.table'); if(!card)return; document.querySelectorAll('.table').forEach(x=>x.classList.remove('sel')); card.classList.add('sel'); const id=String(card.dataset.table).startsWith('table-')?card.dataset.table:`table-${card.dataset.table}`; const found=openOrders.find(o=>String(o.tableId)===id||String(o.tableId)===String(card.dataset.table)); if(found)drawOrder(found); else { currentOrder=null; document.querySelector('.order h2').textContent='Стол '+card.dataset.table; drawOrder({tableId:id,items:[]}); }});
const catalog=document.querySelector('#catalog'), grid=document.querySelector('#catalog-grid'), search=document.querySelector('#product-search');
