const normalizeSearch=(value)=>String(value||'').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
function draw(q=''){const query=normalizeSearch(q);grid.innerHTML=products.filter(([name,,aliases=[]])=>normalizeSearch([name,...aliases].join(' ')).includes(query)).map(([name,price,aliases=[],imageUrl])=>{const id=products.find(x=>x[0]===name)?.[4]||name.toLowerCase().replace(/[^a-z0-9]+/g,'-'); return `<button class="product" data-id="${id}" data-name="${name}" data-price="${price}">${imageUrl?`<img src="${imageUrl}" alt="">`:'<span class="product-placeholder">＋</span>'}<span>${name}</span><b>${price} ₽ &nbsp;＋</b></button>`;}).join('');}
draw(); fetch('/api/products',{headers:sessionHeaders()}).then(r=>r.ok?r.json():null).then(data=>{if(data?.items?.length){products=data.items.map(x=>[x.name,x.price,x.aliases||[],x.imageUrl||null,x.id]);draw(search?.value||'');}}).catch(()=>{}); document.querySelector('.primary')?.addEventListener('click',()=>catalog.classList.add('open')); document.querySelector('#catalog-close')?.addEventListener('click',()=>catalog.classList.remove('open')); search?.addEventListener('input',e=>draw(e.target.value));
function recalc(){const total=[...document.querySelectorAll('.items b')].reduce((s,x)=>s+Number(x.textContent.replace(/[^0-9]/g,'')),0); const el=document.querySelector('#order-total'); if(el)el.textContent=total.toLocaleString('ru-RU')+' ₽';}
grid.addEventListener('click',e=>{const item=e.target.closest('.product'); if(!item)return; const add=order=>apiJson(`/api/orders/${order.id}/items`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({productId:item.dataset.id||item.dataset.name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),quantity:1})}); const finish=order=>add(order).then(created=>{order.items=[...(order.items||[]),{...created,name:created.name||item.dataset.name,unitPrice:Number(item.dataset.price)}]; drawOrder(order); catalog.classList.remove('open');}).catch(()=>{const row=document.createElement('div'); row.innerHTML=`${item.dataset.name} <b>${item.dataset.price} ₽</b>`; orderRows.append(row); recalc(); catalog.classList.remove('open');}); if(currentOrder?.id) finish(currentOrder); else {const tableId=document.querySelector('.table.sel')?.dataset.table||'8'; apiJson('/api/orders',{method:'POST',headers:orderHeaders(),body:JSON.stringify({tableId:String(tableId).startsWith('table-')?tableId:`table-${tableId}`,minimumOrderTotal:tableMinimums[tableId]||0})}).then(order=>{openOrders.push(order);finish(order);}).catch(()=>finish({id:'local-order',tableId,minimumOrderTotal:tableMinimums[tableId]||0,items:[]})); }});
orderRows.addEventListener('click',(event)=>{const button=event.target.closest('[data-item]');if(!button||!currentOrder)return;const item=currentOrder.items.find((entry)=>entry.id===button.dataset.item);if(!item)return;const next=Number(item.quantity||1)+(button.classList.contains('qty-plus')?1:-1);if(next<1){apiJson(`/api/orders/${currentOrder.id}/items/${item.id}`,{method:'DELETE',headers:orderHeaders()}).then(()=>{currentOrder.items=currentOrder.items.filter((entry)=>entry.id!==item.id);drawOrder(currentOrder);}).catch(()=>notice('Не удалось удалить позицию'));return;}apiJson(`/api/orders/${currentOrder.id}/items/${item.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({quantity:next})}).then(()=>{item.quantity=next;drawOrder(currentOrder);}).catch(()=>notice('Не удалось изменить количество'));});
const requestStaffAction=(config={})=>new Promise((resolve)=>{const modal=document.querySelector('#staff-action-modal'),form=document.querySelector('#staff-action-form'),fields=document.querySelector('#staff-action-fields');if(!modal||!form){resolve(null);return;}document.querySelector('#staff-action-title').textContent=config.title||'Действие';document.querySelector('#staff-action-description').textContent=config.description||'';document.querySelector('#staff-action-submit').textContent=config.submitLabel||'Продолжить';document.querySelector('#staff-action-message').textContent='';fields.innerHTML=(config.fields||[]).map((field)=>{const tag=field.type==='select'?'select':field.type==='textarea'?'textarea':'input';const options=field.type==='select'?(field.options||[]).map((option)=>`<option value="${String(option.value).replace(/"/g,'&quot;')}" ${String(option.value)===String(field.value??'')?'selected':''}>${option.label}</option>`).join(''):'';const value=field.type==='select'||field.type==='textarea'?'':`value="${String(field.value??'').replace(/"/g,'&quot;')}"`;return `<label class="action-field">${field.label}<${tag} name="${field.name}" type="${field.type==='select'||field.type==='textarea'?'text':(field.type||'text')}" ${field.required?'required':''} ${field.min!==undefined?`min="${field.min}"`:''} ${field.max!==undefined?`max="${field.max}"`:''} ${field.step!==undefined?`step="${field.step}"`:''} placeholder="${field.placeholder||''}" ${value}>${field.type==='textarea'?String(field.value??''):options}</${tag}></label>`;}).join('');modal.classList.add('open');modal.setAttribute('aria-hidden','false');const finish=(value)=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true');form.onsubmit=null;resolve(value);};form.onsubmit=(event)=>{event.preventDefault();finish(Object.fromEntries(new FormData(form).entries()));};document.querySelector('#staff-action-cancel').onclick=()=>finish(null);document.querySelector('#staff-action-close').onclick=()=>finish(null);modal.onclick=(event)=>{if(event.target===modal)finish(null);};setTimeout(()=>fields.querySelector('input,select,textarea')?.focus(),0);});
document.querySelector('.close')?.addEventListener('click',async()=>{if(!currentOrder?.id){notice('Сначала добавьте позицию в заказ');return;}const choice=await requestStaffAction({title:'Закрыть заказ',description:'Выберите способ оплаты для оставшейся суммы.',submitLabel:'Закрыть заказ',fields:[{name:'method',label:'Способ оплаты',type:'select',options:[{value:'cash',label:'Наличные'},{value:'card',label:'Карта'},{value:'qr',label:'QR'}]}]});if(!choice)return;apiJson(`/api/orders/${currentOrder.id}/close`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({paymentMethod:choice.method})}).then(result=>{const closed=openOrders.find((order)=>order.id===currentOrder.id);if(closed)closed.status='closed';drawQueue();notice(result.minimumAdjustment>0 ? `Заказ закрыт на ${Number(result.finalTotal||0).toLocaleString('ru-RU')} ₽ · доплата до VIP-минимума ${Number(result.minimumAdjustment).toLocaleString('ru-RU')} ₽` : `Заказ закрыт на ${Number(result.finalTotal||0).toLocaleString('ru-RU')} ₽`);currentOrder=null;drawOrder({items:[]});}).catch(()=>notice('Не удалось закрыть заказ'));});
document.querySelector('#discount-request')?.addEventListener('click',async()=>{if(!currentOrder?.id){notice('Сначала откройте заказ');return;}const choice=await requestStaffAction({title:'Запросить скидку',description:'Заявка уйдёт администратору и будет привязана к этому заказу.',submitLabel:'Отправить заявку',fields:[{name:'value',label:'Скидка, %',type:'number',min:1,step:1,placeholder:'10',required:true},{name:'reason',label:'Причина',type:'textarea',placeholder:'Лояльность гостя',required:true}]});if(!choice)return;const value=Number(choice.value);if(!Number.isFinite(value)||value<=0||value>100){notice('Скидка должна быть от 1 до 100%');return;}apiJson(`/api/orders/${currentOrder.id}/discount-requests`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({type:'percent',value,reason:String(choice.reason||'').trim()})}).then(()=>notice('Заявка отправлена администратору')).catch(()=>notice('Не удалось отправить заявку'));});

const notice=(text)=>{let el=document.querySelector('#staff-notice');if(!el){el=document.createElement('div');el.id='staff-notice';el.className='staff-notice';document.body.append(el);}el.textContent=text;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),2400);};
document.querySelectorAll('aside nav button').forEach((button)=>button.addEventListener('click',()=>{
  document.querySelectorAll('aside nav button').forEach((item)=>item.classList.remove('active')); button.classList.add('active');
  const label=button.textContent.trim(); if(label.includes('Бронирования')) window.location.href='/reservations'; else if(label.includes('Склад')) window.location.href='/inventory'; else if(label.includes('Финансы')) window.location.href='/finance'; else if(label.includes('Заказы')||label.includes('Задачи')) { drawQueue(label.includes('Задачи')?'ready':'all'); document.querySelector('.queue')?.scrollIntoView({behavior:'smooth'}); notice(label.includes('Задачи')?'Показаны готовые задачи':'Показаны активные заказы'); } else document.querySelector('.tables')?.scrollIntoView({behavior:'smooth'});
}));
document.querySelector('#shift-toggle')?.addEventListener('click',async()=>{
  const closing=Boolean(currentShift);const choice=await requestStaffAction({title:closing?'Закрыть смену':'Открыть смену',description:closing?'Сверьте фактический остаток в кассе перед закрытием.':'Укажите стартовый остаток в кассе.',submitLabel:closing?'Закрыть смену':'Открыть смену',fields:[{name:closing?'closingCash':'openingCash',label:closing?'Фактическая сумма':'Остаток в кассе',type:'number',min:0,step:.01,placeholder:'0',required:true}]});if(!choice)return;const key=closing?'closingCash':'openingCash';const amount=Number(choice[key]);if(!Number.isFinite(amount)||amount<0){notice('Сумма должна быть неотрицательной');return;}if(closing){shiftApi({url:`/api/shifts/${currentShift.id}/close`,method:'POST',body:JSON.stringify({closingCash:amount})}).then(()=>{currentShift=null;refreshShift();notice('Смена закрыта');}).catch(()=>notice('Не удалось закрыть смену'));return;}shiftApi({method:'POST',body:JSON.stringify({openingCash:amount})}).then((shift)=>{currentShift=shift;refreshShift();notice('Смена открыта');}).catch(()=>notice('Не удалось открыть смену'));
});
document.querySelectorAll('.tabs button').forEach((button)=>button.addEventListener('click',()=>{document.querySelectorAll('.tabs button').forEach((item)=>item.classList.remove('selected'));button.classList.add('selected');const zone=serverZones.find((item)=>item.name.toLowerCase().includes(button.textContent.trim().toLowerCase()));if(zone)renderZone(zone);notice(`Зона «${button.textContent.trim()}» выбрана`);}));
document.querySelectorAll('.actions button').forEach((button)=>button.addEventListener('click',()=>{
  if(!currentOrder?.id){notice('Сначала добавьте позицию в заказ');return;}
  const status=button.textContent.includes('бар')?'in_progress':'ready';
  apiJson(`/api/orders/${currentOrder.id}/status`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({status})}).then(()=>{currentOrder.status=status;const active=openOrders.find((order)=>order.id===currentOrder.id);if(active)active.status=status;drawQueue();notice(status==='in_progress'?'Заказ отправлен на бар':'Задача отправлена кальянщику');}).catch(()=>notice('Не удалось передать заказ'));
}));
document.querySelector('#transfer-order')?.addEventListener('click',()=>{
  if(!currentOrder?.id){notice('Сначала откройте заказ');return;}
  requestStaffAction({title:'Передать заказ',description:'Выберите стол, на который нужно перенести заказ.',submitLabel:'Передать заказ',fields:[{name:'table',label:'Номер стола',type:'number',min:1,max:99,step:1,placeholder:'1',required:true}]}).then((choice)=>{if(!choice)return;const table=Number(choice.table);if(!Number.isInteger(table)||table<1){notice('Укажите корректный номер стола');return;}const tableId=`table-${table}`;apiJson(`/api/orders/${currentOrder.id}/transfer`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({tableId})}).then(()=>{currentOrder.tableId=tableId;document.querySelector('.order h2').textContent=`Стол ${table}`;notice('Заказ передан на новый стол');}).catch(()=>notice('Не удалось передать заказ'));});
});
document.querySelector('#split-order')?.addEventListener('click',()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('В заказе нет позиций для разделения');return;}
  const lines=currentOrder.items.map((item,index)=>`${index+1}. ${item.name||'Позиция'} ×${item.quantity||1}`).join('\n');
  requestStaffAction({title:'Разделить заказ',description:`Выберите номера позиций через запятую.\n${lines}`,submitLabel:'Создать новый заказ',fields:[{name:'items',label:'Номера позиций',type:'text',placeholder:'1, 3',required:true}]}).then((choice)=>{if(!choice)return;const indexes=String(choice.items||'').split(',').map((value)=>Number(value.trim())-1).filter((value)=>Number.isInteger(value)&&value>=0&&value<currentOrder.items.length);const itemIds=[...new Set(indexes)].map((index)=>currentOrder.items[index].id);if(!itemIds.length){notice('Позиции не выбраны');return;}apiJson(`/api/orders/${currentOrder.id}/split`,{method:'POST',headers:orderHeaders(),body:JSON.stringify({itemIds})}).then((target)=>{currentOrder.items=currentOrder.items.filter((item)=>!itemIds.includes(item.id));openOrders.push(target);drawOrder(currentOrder);notice('Новый заказ создан');}).catch(()=>notice('Не удалось разделить заказ'));});
});
const paymentModal=document.querySelector('#payment-modal'); const paymentForm=document.querySelector('#payment-form');
const paymentInputs=['cash','card','qr'].map((method)=>document.querySelector(`#payment-${method}`)).filter(Boolean);
const paymentDue=()=>{const subtotal=(currentOrder?.items||[]).reduce((sum,item)=>sum+Number(item.unitPrice||item.price||0)*Number(item.quantity||1),0);return Math.max(subtotal-localApprovedDiscountTotal(currentOrder?.id,subtotal),Number(currentOrder?.minimumOrderTotal||0));};
const refreshPaymentRemainder=()=>{const due=paymentDue();const paid=paymentInputs.reduce((sum,input)=>sum+Math.max(0,Number(input.value||0)),0);const remainder=document.querySelector('#payment-remaining');if(remainder)remainder.textContent=`Остаток ${Math.max(0,due-paid).toLocaleString('ru-RU')} ₽`;};
paymentInputs.forEach((input)=>input.addEventListener('input',refreshPaymentRemainder));
document.querySelector('#payment-close')?.addEventListener('click',()=>paymentModal?.classList.remove('open'));
paymentModal?.addEventListener('click',(event)=>{if(event.target===paymentModal)paymentModal.classList.remove('open');});
document.querySelector('#split-payment')?.addEventListener('click',()=>{
  if(!currentOrder?.id || !(currentOrder.items||[]).length){notice('Сначала добавьте позиции в заказ');return;}
  const due=paymentDue(); const dueEl=document.querySelector('#payment-due'); if(dueEl)dueEl.textContent=`${due.toLocaleString('ru-RU')} ₽`; paymentInputs.forEach((input)=>{input.value='0';}); const message=document.querySelector('#payment-message'); if(message)message.textContent=''; refreshPaymentRemainder(); paymentModal?.classList.add('open'); paymentInputs[0]?.focus();
});
paymentForm?.addEventListener('submit',async(event)=>{
  event.preventDefault(); const due=paymentDue(); const entries=[['cash','Наличные'],['card','Карта'],['qr','QR']].map(([method])=>({method,amount:Number(document.querySelector(`#payment-${method}`)?.value||0)})).filter((entry)=>entry.amount>0); const total=entries.reduce((sum,entry)=>sum+entry.amount,0); const message=document.querySelector('#payment-message'); if(!entries.length||total>due+0.01){if(message)message.textContent=total>due?'Сумма платежей больше суммы заказа.':'Укажите хотя бы один способ оплаты.';return;} try { let paid=0; for(const entry of entries){const result=await apiJson(`/api/orders/${currentOrder.id}/payments`,{method:'POST',headers:orderHeaders(),body:JSON.stringify(entry)});paid=Number(result.paid||paid+entry.amount);currentOrder.paid=paid;currentOrder.remaining=Number(result.remaining||0);currentOrder.status=result.closed?'closed':currentOrder.status;} paymentModal.classList.remove('open'); if (paid>=due) { currentOrder.status='closed'; const active=openOrders.find((order)=>order.id===currentOrder.id); if(active) active.status='closed'; drawQueue(); } notice(paid>=due?'Заказ оплачен частями':'Платёж сохранён, остаток '+(due-paid).toLocaleString('ru-RU')+' ₽'); } catch (_) {if(message)message.textContent='Не удалось записать платеж. Проверьте данные и повторите.';}
});
document.querySelectorAll('.order-tabs span').forEach((tab)=>tab.addEventListener('click',()=>{
  if(!currentOrder){notice('Сначала выберите стол');return;}
  if(tab.textContent.trim()==='Гости'){requestStaffAction({title:'Гость в заказе',description:'Сохраните контакт, чтобы скидка и история были привязаны к заказу.',submitLabel:'Сохранить гостя',fields:[{name:'guests',label:'Количество гостей',type:'number',min:1,step:1,value:currentOrder.guests||2,placeholder:'2',required:true},{name:'guestName',label:'Имя гостя',type:'text',value:currentOrder.guestName||'',placeholder:'Имя и фамилия'},{name:'phone',label:'Телефон',type:'tel',value:currentOrder.guestPhone||'',placeholder:'+7 (___) ___-__-__'}]}).then((choice)=>{if(!choice)return;const guests=Number(choice.guests);if(!Number.isInteger(guests)||guests<1){notice('Количество гостей должно быть не меньше одного');return;}apiJson(`/api/orders/${currentOrder.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({guestName:String(choice.guestName||'').trim(),phone:String(choice.phone||'').trim()})}).then((saved)=>{currentOrder.guests=guests;currentOrder.guestName=saved.guestName||String(choice.guestName||'').trim();currentOrder.guestPhone=saved.phone||String(choice.phone||'').trim();drawOrder(currentOrder);notice('Гость привязан к заказу');}).catch(()=>notice('Не удалось сохранить гостя'));});return;}
  requestStaffAction({title:'Заметка к заказу',description:'Комментарий будет виден сотрудникам, которые обслуживают этот заказ.',submitLabel:'Сохранить заметку',fields:[{name:'notes',label:'Комментарий',type:'textarea',value:currentOrder.notes||'',placeholder:'Например: без мяты, подать после кальяна'}]}).then((choice)=>{if(!choice)return;const value=String(choice.notes||'').trim();apiJson(`/api/orders/${currentOrder.id}`,{method:'PATCH',headers:orderHeaders(),body:JSON.stringify({notes:value})}).then(()=>{currentOrder.notes=value;notice(value?'Заметка сохранена':'Заметка очищена');}).catch(()=>notice('Не удалось сохранить заметку'));});
}));
document.querySelectorAll('.chips span').forEach((chip)=>chip.addEventListener('click',()=>{drawQueue(chip.dataset.filter||'all');notice(`Фильтр «${chip.textContent.trim().replace(/\s+\d+$/,'')}» применён`);}));
document.querySelector('#queue-list')?.addEventListener('click',(event)=>{const card=event.target.closest('[data-queue-table]');if(!card)return;const table=document.querySelector(`.table[data-table="${card.dataset.queueTable}"]`);if(table)table.click();document.querySelector('.workspace')?.scrollIntoView({behavior:'smooth',block:'start'});});

